// Package id holds OpenMRP's ID prefix vocabulary and prefixes. IDs are generated by apikit's id package; the
// aliases here let callers name the prefix, the length and GenID through one import.
package id

import (
	"github.com/open-mrp/apikit/apierror"
	apikitid "github.com/open-mrp/apikit/id"
)

// IDPrefix is the type-specific part of an ID, composed from the vocabulary below.
type IDPrefix = apikitid.IDPrefix

// IDLength is the length of an ID's random part.
type IDLength = apikitid.IDLength

const (
	IDLength12 = apikitid.IDLength12
	IDLength19 = apikitid.IDLength19
	IDLength22 = apikitid.IDLength22
)

// MaxLength is the longest ID GenID returns for any prefix. Columns sized to it rather than
// varchar(191) (sales_line_fact's, to fit a wide covering key) would reject a longer one.
const MaxLength = 64

// GenID returns a new ID with prefix and a random part of length (12 when nil).
func GenID(prefix IDPrefix, length *IDLength) (string, *apierror.APIError) {
	return apikitid.GenID(prefix, length)
}
